<?php use App\Services\Navigation;use App\Models\Content;$dropdown=$item['menu_type']!=='link';$href=cms_url($link);$current=request_path();$targetPath=parse_url($link,PHP_URL_PATH)?:'';$active=$item['active_match']==='exact'?rtrim($targetPath,'/')===rtrim($current,'/'):($item['active_match']==='prefix'&&$targetPath!=='/'&&str_starts_with($current,rtrim($targetPath,'/')));?>
<li class="nav-item <?=$dropdown?'dropdown':''?> <?=$active?'active':''?> cms-nav-<?=e($item['visibility'])?>"><a href="<?=e($href)?>" class="nav-link" target="<?=e($item['target'])?>" <?=$item['target']==='_blank'?'rel="noopener noreferrer"':''?> <?=$dropdown?'aria-expanded="false"':''?>><?php if($item['icon']):?><i class="<?=e($item['icon'])?>"></i> <?php endif?><?=e($item['title'])?><?php if($dropdown):?><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="M6 9l6 6 6-6"/></svg><?php endif?></a>
<?php if($dropdown):?><div class="mega-menu <?=$item['display_style']==='brands'?'brands-mega-menu':''?> <?=$item['menu_type']==='dropdown'?'cms-simple-dropdown':''?>">
<?php if($item['menu_type']==='mega'):$groups=Content::published('mega_menu_groups','navigation_item_id=?',[$item['id']]);?><div class="row g-4"><?php foreach($groups as $group):?><div class="<?=$item['display_style']==='brands'?'col-12':'col-md-'.(12/(int)$item['columns'])?>"><div class="menu-group"><div class="menu-group-title"><?php if($group['icon']):?><i class="<?=e($group['icon'])?>"></i><?php endif?><?=e($group['title'])?></div><?php if($group['image_id']):?><?=media_img($group['image_id'],$group['title'],'cms-menu-image')?><?php endif?><div class="<?=$item['display_style']==='brands'?'brands-dropdown-scroll':''?>"><div class="<?=$item['display_style']==='brands'?'row g-2':''?>"><?php foreach(Navigation::groupItems($group) as $entry):$entryLink=Navigation::link($entry);if($entryLink===null)continue;?><?php if($item['display_style']==='brands'):?><div class="col-6 col-md-4"><?php endif?><a class="menu-item" href="<?=e(cms_url($entryLink))?>" target="<?=e($entry['target']??'_self')?>" rel="noopener noreferrer"><?php if($entry['image_id']??null):?><?=media_img($entry['image_id'],$entry['title'],'nav-product-thumb')?><?php else:?><i class="<?=e(($entry['icon']??'')?:'fa-solid fa-box')?>"></i><?php endif?><span><?=e($entry['title'])?><?php if(!empty($entry['description'])):?><p class="item-desc"><?=e(mb_strimwidth(strip_tags($entry['description']),0,48,'…'))?></p><?php endif?></span></a><?php if($item['display_style']==='brands'):?></div><?php endif?><?php endforeach?></div></div><?php if($group['button_label']):?><a class="view-all" href="<?=e(cms_url($group['button_url']))?>"><?=e($group['button_label'])?></a><?php endif?></div></div><?php endforeach?></div><?php endif?>
<ul class="cms-nested-links"><?php Navigation::renderItems($items,(int)$item['id'],$depth+1);?></ul></div><?php endif?></li>
